namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) });
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) });
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) });
    }

    /// <summary>
    /// Returns all notifications.
    /// </summary>
    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given ID.
    /// Simulates new notifications arriving periodically.
    /// </summary>
    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            // Simulate a new notification roughly every other poll
            if (Random.Shared.Next(2) == 0)
            {
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                    Timestamp = DateTime.UtcNow
                });
            }

            var newer = _notifications.Where(n => n.Id > lastSeenId).ToList();
            return Task.FromResult(newer);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Timestamp.ToString("HH:mm:ss")</strong> &mdash; @n.Message
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem> notifications { get; set; } = new();

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // Only load if not already restored from prerender state
        if (notifications.Count == 0)
        {
            notifications = await NotificationService.GetNotificationsAsync();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive in the browser
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
                var newer = await NotificationService.GetNotificationsSinceAsync(lastId);

                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

